-- 028: Upload Inventory dengan SKU resmi + ID PENDING untuk item yang belum ada SKU.
-- WAJIB: jalankan sesudah 025, 026, 027. Backup database, hentikan upload dan counting saat migrasi.
-- Tidak ada inventaris / SO / BA historis yang dihapus oleh skrip migrasi ini.
-- SKU PENDING adalah IDENTITAS TEKNIS sementara, BUKAN kode SKU resmi Moka.
-- Jangan gunakan PENDING untuk posting adjust ke Moka tanpa pemetaan manual.
BEGIN;
DO $prereq$ BEGIN
 IF to_regclass('public.tsi_so_item_sku_map') IS NULL THEN
  RAISE EXCEPTION 'Migrasi 026 belum dipasang (tsi_so_item_sku_map tidak ditemukan).';
 END IF;
END $prereq$;
CREATE TABLE IF NOT EXISTS public.tsi_so_item_pending_map (
 item_key text PRIMARY KEY, item_name text NOT NULL,
 category text NOT NULL DEFAULT '', item_variant_id text NOT NULL UNIQUE
);
ALTER TABLE public.tsi_so_item_pending_map ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.tsi_so_item_pending_map FROM PUBLIC,anon,authenticated;
